#include <print>
#include <memory>
#include <string>

int main() {
    auto a = std::make_shared<std::string>("共享数据");
    std::println("刚创建，计数 = {}", a.use_count());
    {
        auto b = a;
        auto d = b;
        std::println("三张在手，计数 = {}", d.use_count());
    }
    std::println("他们走了，计数 = {}", a.use_count());
    std::println("数据还在: {}", *a);
    return 0;
}
// 计数从 1 涨到 3，格子一合上又落回 1：对象始终是同一个

